# פרק 2 (שלד אוטומטי מהתוכן הקיים; להעמקה)
N=2
TITLE='עוולת הרשלנות — חובת זהירות'
SUM=[' <p>עוולת המסגרת המרכזית. שלושה יסודות: <strong>חובת זהירות</strong>, <strong>התרשלות</strong>, ו<strong>נזק</strong> (בקשר סיבתי). שיעור זה — היסוד הראשון.</p> <h3>2.1 המקור — סעיפים 35–36</h3> <p><strong>סעיף 35</strong> מגדיר את הרשלנות; <strong>סעיף 36</strong> מתחם את היקף חובת הזהירות — היא מוטלת כלפי כל אדם כל אימת ש<strong>אדם סביר</strong> צריך היה לראות מראש שייפגע ממעשהו או ממחדלו.</p> <h3>2.2 חובת זהירות מושגית וקונקרטית</h3> <p>ה<strong>מושגית</strong> היא שאלה קטגורית — האם קיימת חובה בין סוג מזיקים לסוג ניזוקים (נהג כלפי הולכי רגל), לפי הצפיות ושיקולי מדיניות. ה<strong>קונקרטית</strong> היא שאלה פרטנית — האם בנסיבות המקרה חב המזיק חובה לניזוק זה (האם הנזק הספציפי היה צפוי).</p> <h3>2.3 מבחן הצפיות — ועקנין</h3> <p>ב<strong>ועקנין נ\' המועצה המקומית בית שמש</strong> ביסס ברק את המבנה הדו-שלבי, וההבחנה בין <strong>צפיות טכנית</strong> (יכולת לצפות) לבין <strong>צפיות נורמטיבית</strong> (האם ראוי לדרוש צפייה).</p> <h3>2.4 נקודות מפתח למבחן</h3> <ul><li>שלושת יסודות הרשלנות; חובת זהירות = יסוד ראשון.</li><li>מושגית (קטגורית) מול קונקרטית (פרטנית).</li><li>מבחן הצפיות — טכנית מול נורמטיבית (ועקנין).</li></ul> <p style="margin-top:18px;padding-top:9px;border-top:1px solid var(--line,#3a342a);font-size:11px;color:var(--muted,#8a8475)">© כל הזכויות שמורות ל<b>אילן פרץ</b> · אין להעתיק, לשכפל או להפיץ ללא רשות בכתב.</p>']
CASES=[('ע"א 145/80 ועקנין נ\' המועצה המקומית בית שמש, פ"ד לז(1) 113', '', 'פסק הדין המכונן בעוולת הרשלנות: המבנה הדו-שלבי של חובת הזהירות (מושגית וקונקרטית) וההבחנה בין צפיות טכנית לנורמטיבית.'), ("ס' 36 לפקודת הנזיקין — היקף החובה", '', 'חובת הזהירות מוטלת כלפי כל מי שאדם סביר צריך היה לצפות שייפגע ממעשה/מחדל.'), ('מבחן הצפיות', '', 'הכלי לקביעת חובת הזהירות — צפיות טכנית (יכולת) לצד צפיות נורמטיבית (חובה ערכית), בשילוב שיקולי מדיניות.'), ('ע״א 145/80 ועקנין נ׳ המועצה המקומית בית שמש, פ״ד לז(1) 113', 'נער כבן 15 קפץ קפיצת ראש לחלק הרדוד של בריכה ונפצע קשה. במקום לא הוצבו שלטים שאוסרים קפיצה, כפי שדרשו תקנות רישוי העסקים.', 'השופט ברק פיתח את המבנה של חובה מושגית (קטגוריות) וחובה קונקרטית (המקרה), ואת ההבחנה בין צפיות טכנית לצפיות נורמטיבית, שבה נשקלים שיקולי מדיניות. חובה קונקרטית קמה רק לגבי סיכון בלתי סביר: רצפה חלקה בבית מרחץ היא סיכון רגיל של החיים, אבל קפיצה למים רדודים היא סיכון חמור שאמצעי מניעה זולים יכולים למנוע. הבעלים והמפעיל חבו חובת זהירות.'), ('ע״א 243/83 עיריית ירושלים נ׳ גורדון, פ״ד לט(1) 113 (1985)', 'תביעה נגד עירייה בגין נזק לא גופני שנגרם לתובע מהתנהלותה הרשלנית.', 'נקבע הכלל: במקום שהנזק צפוי פיזית, יש חובה לצפותו נורמטיבית, אלא אם קיימים שיקולים מיוחדים שמצדיקים לצמצם את החובה או לשלול אותה. הוכר פיצוי על נזק נפשי בלי ביטוי פיזי, ונקבע ששאלת האחריות לנזק כלכלי טהור תוכרע לפי שיקולי מדיניות ולא תישלל באופן גורף.'), ('ע״א 915/91 מדינת ישראל נ׳ לוי, פ״ד מח(3) 45 (1994)', 'נטען שהמפקח על הביטוח התרשל כשלא הפסיק בזמן את פעילותה של חברת ביטוח שקרסה, ולכן תלויים במי שנהרג בתאונת דרכים לא קיבלו פיצוי.', 'הנשיא שמגר הציע להתמקד בחובה הקונקרטית, שבנויה מצפיות, שכנות וקרבה, ושאלה אם הוגן, צודק וסביר להטיל חובה. נקבע שלא כל אחריות ציבורית או מוסרית של השלטון יוצרת אחריות ברשלנות, והוכר "חריג שיקול הדעת" לגבי החלטות שלטוניות שכרוכות באיזון רחב של שיקולים. על המדינה לא הוטלה אחריות.'), ('ע״א 10078/03 שתיל נ׳ מקורות חברת מים בע״מ, פ״ד סב(1) 803 (2007)', 'חקלאי שגידל פרחים טען שהמדינה וגופים מטעמה התרשלו כשהשתהו שנים בפתרון בעיית המליחות של המים שסופקו לו, וכך נגרם נזק לגידוליו.', 'השופט א׳ א׳ לוי הציע לבחון קודם את ההתרשלות, ורק אחריה את החובה הקונקרטית (שכנות ושיקולי מדיניות), כי החובה המושגית כמעט אינה מסננת תיקים. הוטל גם ספק בהצדקה ל"חריג שיקול הדעת" כפטור גורף לרשויות.'), ('ע״א 3521/11 עו״ד וגנר נ׳ עבדי, פ״ד סז(1) 84 (2014)', 'כספי הלוואת משכנתא הועברו לעורך דין והופקדו בחשבון נאמנות בבנק אחר, ונעלמו בהונאה. נדון אם עורך הדין והבנק המחזיק חבו חובת זהירות כלפי הבנק המלווה.', 'השופט הנדל קבע שיש לשמור על המבנה המסורתי (חובה ואחר כך הפרה), אבל לבחון את החובה לפי סוגה: חובה מוכרת מחייבת בדיקה קונקרטית בלבד, חובה חדשה מחייבת בדיקה מושגית מלאה, ובחובה גבולית בודקים אם החובה העקרונית חלה על תת־המקרה. זו הגישה הגמישה הנוהגת היום.'), ('רע״א 444/87 אלסוחה נ׳ עיזבון המנוח דוד דהאן ז״ל (1990)', 'הורים של ילד בן כשש שנפגע בתאונת דרכים ישבו לצידו בבית החולים 24 ימים עד מותו, ולקו בנפשם. בערעור נוסף נדונה בת שראתה את אמה הפצועה ואחר כך את גופתה.', 'הנשיא שמגר קבע שבחובה המושגית לגבי נפגעים משניים נדרש סינון, וקבע ארבעה שיקולים: זהות התובע (ככלל קרוב מדרגה ראשונה), התרשמות ישירה מהאירוע או מתוצאותיו, קרבה בזמן ובמקום (כולל בית החולים וחשיפה מתמשכת), ונזק נפשי ממשי וקשה. תביעת ההורים התקבלה.'), ('ע״א 6313/19 רשות ניירות ערך נ׳ שמואל (11.4.2022)', 'משקיעים איבדו את כספם בחברה שניהלה השקעות ממוחשבות בלי רישיון. הם תבעו את רשות ניירות ערך על מחדלים באכיפה, כמו השתהות בבקשת צו מניעה ובפרסום אזהרה.', 'בדעת רוב (השופטים מינץ וגרוסקופף) התקבל ערעור הרשות והיא נפטרה מאחריות. השופט מינץ קבע שאחריות נזיקית של רשויות בגין פיקוח ואכיפה תוטל רק במקרים חריגים ונדירים, ובמיוחד כשמדובר במאסדר. השופט גרוסקופף קבע שלא הוכח קשר סיבתי. המשנה לנשיאה הנדל, בדעת מיעוט, הכיר בחובת זהירות על בסיס סמכויות האכיפה והטיל אחריות עם אשם תורם של 50%.')]
QS=[{'q': 'לפי מבנה ס׳ 35, מה ההבדל בין "התרשלות" לבין "רשלנות"?', 'o': ['רשלנות היא התרשלות כלפי אדם שהמזיק חב כלפיו חובה באותן נסיבות', 'אין הבדל, אלה מילים נרדפות', 'התרשלות היא מעשה, ורשלנות היא מחדל', 'רשלנות דורשת כוונה, והתרשלות לא'], 'c': 0, 'e': 'נכון. ההתרשלות היא סטייה מהאדם הסביר. הרשלנות מוסיפה את יסוד החובה, והעוולה מוסיפה נזק שנגרם.'}, {'q': 'מה ההבדל בין צפיות טכנית לצפיות נורמטיבית?', 'o': ['טכנית בודקת אם אפשר היה לצפות את הנזק, ונורמטיבית בודקת אם צריך היה לצפות אותו, לפי שיקולי מדיניות', 'טכנית שייכת לחובה הקונקרטית בלבד, ונורמטיבית למושגית בלבד', 'טכנית נבחנת לפי המזיק הסובייקטיבי, ונורמטיבית לפי מומחה', 'אין הבדל של ממש'], 'c': 0, 'e': 'נכון. כמעט כל נזק צפוי טכנית. השאלה הנורמטיבית מסננת ושוקלת אם ראוי להטיל חובה.'}, {'q': 'מה קובעת הלכת גורדון כנקודת מוצא לגבי חובת הזהירות?', 'o': ['אין חובה אלא אם התובע מוכיח שכנות מיוחדת', 'חובה קמה רק בנזקי גוף', 'במקום שהנזק צפוי פיזית, יש חובה לצפותו נורמטיבית, אלא אם שיקולים מיוחדים שוללים או מצמצמים את החובה', 'חובה קמה רק כלפי צדדים לחוזה'], 'c': 2, 'e': 'נכון. זה הכלל של ברק בגורדון. הנטל לשכנע בשיקולים ששוללים את החובה הוא מעשית על מי שטוען לצמצום.'}, {'q': 'מה עיקר הביקורת של הנשיא שמגר בעניין לוי על המודל של ברק?', 'o': ['שאין לבחון שיקולי מדיניות כלל', 'ששלב החובה המושגית מיותר, כי ביהמ״ש דן תמיד ביחסים בין מזיק מסוים לניזוק מסוים, ולכן יש לבחון חובה קונקרטית שכוללת צפיות, שכנות ושאלה אם הוגן להטיל חובה', 'שיש לבטל את דרישת הצפיות', 'שרשויות לעולם אינן חבות ברשלנות'], 'c': 1, 'e': 'נכון. שמגר המיר את המבנה הדו־שלבי במבחן קונקרטי משולש והוסיף דרישת שכנות מפורשת.'}, {'q': 'לפי הלכת וגנר נ׳ עבדי, מתי יש לנתח את החובה המושגית לעומק?', 'o': ['כשמדובר בחובה חדשה או גבולית, ולא בחובה מוכרת', 'אף פעם, כי החובה המושגית בוטלה', 'בכל תיק רשלנות, בלי יוצא מן הכלל', 'רק בתביעות נגד רשויות'], 'c': 0, 'e': 'נכון. בחובה מוכרת בודקים רק את החובה הקונקרטית. בחדשה בודקים את המושגית. בגבולית בודקים אם החובה המוכרת חלה על תת־המקרה.'}, {'q': 'למה המשפט מהסס להטיל חובת זהירות בשל מחדל?', 'o': ['כי חובת עשייה פוגעת בחירות יותר מאיסור על מעשה מזיק, וקשה לתחום את מעגל החייבים', 'כי מחדל נחשב תמיד מעשה של מה בכך', 'כי ס׳ 35 חל רק על מעשים', 'כי מחדל לעולם לא גורם נזק'], 'c': 0, 'e': 'נכון. לכן נדרש יסוד נוסף, כמו שליטה, יחסים מיוחדים, יצירת סיכון או הסתמכות, כדי שתקום חובה לפעול.'}, {'q': 'מתרחץ החליק על רצפה רטובה ליד בריכה ציבורית ונחבל קלות. הבריכה מתוחזקת כרגיל. לפי הלכת ועקנין, מה הסיכוי שתוכר חובה קונקרטית לגבי הסיכון הזה?', 'o': ['אפסי, כי לבעלי בריכות אין חובת זהירות', 'נמוך, כי רצפה רטובה ליד בריכה היא סיכון רגיל של החיים ולא סיכון בלתי סביר', 'גבוה, כי לבריכה יש חובה מושגית', 'גבוה, כי הנזק צפוי טכנית'], 'c': 1, 'e': 'נכון. ברק הדגים בדיוק כך: מתרחץ לא יכול להלין על רצפה חלקה, כי זה סיכון שהחברה רואה כרגיל. לעומת זאת, קפיצה למים רדודים היא סיכון חמור.'}, {'q': 'אדם עמד על שפת הים וראה זר טובע. הוא יכול היה לזרוק לו גלגל הצלה ולא עשה דבר. הזר טבע. המשפחה תובעת ברשלנות. מה הניתוח הנכון?', 'o': ['זה מחדל של אדם בלי יחסים מיוחדים עם הטובע, בלי שליטה ובלי שיצר את הסיכון, ולכן קשה להטיל חובת זהירות בנזיקין, אם כי חוק לא תעמוד על דם רעך מטיל חובת הצלה', 'האיש חב בוודאות, כי הנזק היה צפוי לו', 'האיש חב רק אם הוא מציל מוסמך', 'האיש פטור כי ס׳ 35 לא חל על מחדל'], 'c': 0, 'e': 'נכון. אלה הכללים לגבי מחדל. שאלת השימוש בחוק לא תעמוד על דם רעך כבסיס לאחריות נזיקית שייכת להפרת חובה חקוקה (שיעור 7).'}, {'q': 'נוסע הותקף בידי אדם זר בתחנה מרכזית של חברת תחבורה. התחנה בשליטת החברה, והיו תקריות דומות בעבר. האם יכולה לקום לחברה חובת זהירות?', 'o': ['לא, כי המזיק הישיר הוא צד שלישי', 'כן. שליטה במקום, יחסים עם הנוסעים וצפיות הסיכון יכולים להקים חובה גם לגבי נזק שגרם צד שלישי', 'כן, אבל רק אם החברה הסכימה לכך בחוזה', 'לא, כי אין חובה למנוע עבירות'], 'c': 1, 'e': 'נכון. כך עלה בעניין ולעס נ׳ אגד, שבו נדונה חובתה של אגד כלפי נוסע שהותקף בידי זר בתחנה המרכזית (התיק הוחזר למחוזי לבחינת ההתרשלות).'}, {'q': 'נער נכנס בלילה לאתר בנייה סגור כדי לגנוב ציוד, נפל לבור ונפצע. הוא תובע את בעל האתר בגין מצב המקרקעין. מה הדין?', 'o': ['בעל האתר פטור רק אם הציב שלט', 'בעל האתר חב רק אם הנער מתחת לגיל 12', 'בעל האתר חב תמיד, כי הבור היה צפוי', 'בעל האתר לא חב בשל מצב המקרקעין כלפי מסיג גבול, אלא אם הנער יוכיח שנכנס בתום לב ובלי כוונה לעבור עבירה או לעשות עוולה, וזה לא המקרה'], 'c': 3, 'e': 'נכון. ס׳ 37 שולל את החובה של בעל מקרקעין או תופשם בשל מצבם כלפי מסיג גבול, למעט מי שנכנס בתום לב ובלי כוונה עבריינית.'}, {'q': 'אב שמע בטלפון שבתו נפגעה בתאונה. הוא הגיע לבית החולים כעבור שעתיים, ראה אותה במצב קשה, ולקה בהפרעה נפשית קשה ומאובחנת. איזה מבחן יחול על תביעתו נגד הנהג?', 'o': ['מבחני אלסוחה לנפגע משני: קרבה מדרגה ראשונה, התרשמות מהתוצאות המיידיות, קרבה בזמן ובמקום (כולל בית החולים), ונזק נפשי ממשי', 'אין לו עילה, כי לא נכח בתאונה', 'רק צער ויגון, שאינם ברי פיצוי', 'הכללים הרגילים של נפגע ישיר, בלי סינון'], 'c': 0, 'e': 'נכון. ייתכן שיוכר כנפגע משני, כי כל ארבעת השיקולים מתקיימים לכאורה.'}, {'q': 'קבלן פגע ברשלנות בכבל חשמל ציבורי, והחשמל באזור התעשייה נותק לשמונה שעות. עשרות מפעלים תובעים את אובדן הרווחים. מה הקושי העיקרי בתביעה?', 'o': ['זה נזק כלכלי טהור. יש חשש לאחריות בלתי מוגבלת ומתגלגלת, ולכן השאלה תוכרע לפי שיקולי מדיניות', 'הקושי היחיד הוא הוכחת גובה הנזק', 'אין קושי, כי הנזק צפוי ולכן יש חובה', 'הקבלן חסין כי עבד עבור רשות'], 'c': 0, 'e': 'נכון. בישראל אין שלילה גורפת (גורדון, פז נ׳ מדינת ישראל), אבל מעגל הניזוקים הרחב והחשש מתביעות מתגלגלות עשויים להביא לשלילת החובה.'}, {'q': 'עירייה ידעה במשך חודשים שעסק מסוכן פועל בתחומה בלי רישיון, ולא השתמשה בכלים שעמדו לרשותה, כמו קנסות או צו סגירה. לקוח נפצע בעסק. לפי הלכת מימוני, מה הדין?', 'o': ['העירייה לא חבה, כי המזיק הישיר הוא בעל העסק', 'העירייה חסינה, כי מדובר בשיקול דעת שלטוני', 'העירייה חבה רק אם היא בעלת המקרקעין', 'לסמכויות הפיקוח שלה יש משקל: הן יוצרות חובת זהירות כלפי המשתמשים בשירותי העסק, והימנעות מוחלטת מהפעלתן כשהיא יודעת על הסיכון עשויה להיות הפרה'], 'c': 3, 'e': 'נכון. כך נקבע במימוני. עם זאת, לאחר עניין רשות ניירות ערך (2022) יש לזכור את הגישה המצמצמת לגבי פיקוח של מאסדרים.'}, {'q': 'עובד ציבור טעה ברשלנות בעת ביצוע תפקידו השלטוני. נגד מי תופנה התביעה?', 'o': ['נגד המדינה. העובד חסין לפי ס׳ 7א, אלא אם פעל ביודעין בכוונה להזיק או בשוויון נפש', 'נגד העובד בלבד, כי הוא שהתרשל', 'נגד שניהם יחד, תמיד', 'נגד אף אחד, כי פעולה שלטונית חסינה'], 'c': 0, 'e': 'נכון. החסינות האישית של העובד לא גורעת מאחריות המדינה (ס׳ 7א(ב)).'}, {'q': 'מה הכריע הרוב בעניין רשות ניירות ערך נ׳ שמואל (2022)?', 'o': ['שערעור הרשות התקבל והיא פטורה, כי אחריות על פיקוח ואכיפה של מאסדר תוטל רק במקרים חריגים, ובנוסף לא הוכח קשר סיבתי', 'שרשויות חסינות לחלוטין מתביעות נזיקין', 'שהרשות חבה במלוא נזקי המשקיעים', 'שהרשות חבה, עם אשם תורם של 50%'], 'c': 0, 'e': 'נכון. השופט מינץ הדגיש שאחריות כזו מוטלת רק במקרים חריגים ונדירים, והשופט גרוסקופף התמקד בהיעדר קשר סיבתי.'}, {'q': 'מה קבע הנשיא שמגר בעניין אלסוחה לגבי זהות התובע בנזק נפשי משני?', 'o': ['שרק הורים יכולים לתבוע', 'שכל אדם שנפגע נפשית יכול לתבוע', 'שרק מי שנכח בזירה יכול לתבוע', 'שככלל התביעה מותרת לקרובים מדרגה ראשונה (הורים, ילדים, בני זוג), ובמקרים חריגים אפשר לשקול גם קרבה אחרת'], 'c': 3, 'e': 'נכון. זה השיקול הראשון מבין הארבעה, וביהמ״ש השאיר פתח לקרבה אחרת בנסיבות מיוחדות.'}, {'q': 'מה נקבע בעניין המר נ׳ עמית (2012)?', 'o': ['שבוטלה תביעת ההורים והושארה תביעת היילוד', 'שרופאים פטורים מאחריות בייעוץ גנטי', 'שהוכרה לראשונה עילת "החיים בעוולה"', 'שבוטלה עילת "החיים בעוולה" של היילוד, ובמקביל הורחבה תביעת ההורים ("הולדה בעוולה")'], 'c': 3, 'e': 'נכון. ביהמ״ש בהרכב מורחב קבע שאין לראות בחיים עם מוגבלות "נזק", ופיצה על צורכי הילד דרך תביעת ההורים.'}, {'q': 'מה ייחד את עמדת השופט א׳ א׳ לוי בעניין שתיל?', 'o': ['שיש לחזור למשפט האנגלי', 'שיש להעניק לרשויות חסינות מלאה', 'שיש לבחון קודם את ההתרשלות ואחריה את החובה הקונקרטית, כי החובה המושגית כמעט אינה מסננת', 'שיש לבטל את דרישת הנזק'], 'c': 2, 'e': 'נכון. הוא הציע סדר בדיקה הפוך, והטיל ספק בחריג שיקול הדעת כפטור גורף.'}, {'q': 'לפי לשון ס׳ 36 לפקודה, כלפי מי מוטלת חובת הזהירות?', 'o': ['כלפי כל אדם וכלפי בעל כל נכס, כל אימת שאדם סביר צריך היה לראות מראש שהם עלולים להיפגע במהלכם הרגיל של דברים', 'רק כלפי מי שנמצא בשטח שבבעלות המזיק', 'רק כלפי צדדים לחוזה עם המזיק', 'רק כלפי מי שהמזיק מכיר אישית'], 'c': 0, 'e': 'נכון. זו לשון הסעיף. המילה "צריך" מעגנת את הממד הנורמטיבי של הצפיות.'}, {'q': 'לפי לשון ס׳ 37, מתי חב בעל מקרקעין כלפי מסיג גבול בשל מצב המקרקעין?', 'o': ['תמיד, כמו כלפי כל אדם', 'אם הוכיח התובע שנכנס בתום לב ובלי כוונה לעבור עבירה או לעשות עוולה', 'רק אם מסיג הגבול קטין', 'לעולם לא'], 'c': 1, 'e': 'נכון. הנטל להוכיח את תום הלב מוטל על התובע.'}, {'q': 'היכן מעוגנת עוולת הרשלנות?', 'o': ["ס' 12 חוק החוזים", "ס' 35-36 פקודת הנזיקין", "ס' 63", 'חוק יסוד'], 'c': 1, 'e': 'עוולת המסגרת המרכזית.'}, {'q': 'חובת זהירות מושגית בוחנת:', 'o': ['את הנסיבות הספציפיות', 'יחס קטגורי בין סוגי מזיקים לניזוקים', 'את גובה הנזק', 'אשם תורם'], 'c': 1, 'e': 'שאלה עקרונית.'}, {'q': 'חובת זהירות קונקרטית בוחנת:', 'o': ['קטגוריות', 'את נסיבות המקרה הספציפי', 'מדיניות בלבד', 'עלות מניעה'], 'c': 1, 'e': 'האם הנזק הספציפי צפוי.'}, {'q': 'צפיות "טכנית" שואלת:', 'o': ['האם צריך לצפות', 'האם יכול לצפות', 'מה העלות', 'מי אשם'], 'c': 1, 'e': 'יכולת הצפייה בפועל.'}, {'q': 'צפיות "נורמטיבית" שואלת:', 'o': ['האם יכול', 'האם צריך לצפות (ערכי)', 'גובה הנזק', 'זהות הניזוק'], 'c': 1, 'e': 'שיקול מדיניות.'}]
